#!/usr/bin/env bash
set -euo pipefail

# apply-aamend-update-v9.sh
# Run this from inside your local "aamend" repo checkout, e.g.:
#   cd ~/Desktop/aamend   (or wherever you cloned it)
#   chmod +x apply-aamend-update-v9.sh
#   ./apply-aamend-update-v9.sh
#
# What this does:
#  - browser tab title -> just "Amend"
#  - Pics page: split-flap ("airport board") caption under each photo,
#    showing the real geocoded place name where available
#  - fixes 44 more sideways/upside-down photos on the Pics page
#    (in both img/pics/ and img/pics-thumb/)
#  - git add/commit/push

if [ ! -f server.js ] || [ ! -d img ]; then
  echo "This does not look like the aamend repo root (no server.js / img/ found)."
  echo "cd into your aamend checkout first, then re-run this script."
  exit 1
fi

echo "Writing updated files..."

mkdir -p "$(dirname "index.html")"
cat > 'index.html' <<'__AAMEND_V9_EOF_index_html__'
<!DOCTYPE html>
<html lang="en">
<head>
